content:
@media print {
  @page {
    margin: 18mm;
  }

  html,
  body,
  #root,
  .app {
    width: auto !important;
    height: auto !important;
    min-height: 0 !important;
    overflow: visible !important;
    background: #fff !important;
    color: #111 !important;
  }

  .app-header,
  .panel,
  .rail,
  .editor,
  .status-bar,
  .resize-handle,
  .formatting-toolbar,
  .command-palette,
  button {
    display: none !important;
  }

  .workspace,
  .center,
  .preview {
    display: block !important;
    width: auto !important;
    height: auto !important;
    min-height: 0 !important;
    overflow: visible !important;
    margin: 0 !important;
    padding: 0 !important;
    background: #fff !important;
  }

  .preview-body {
    display: block !important;
    max-width: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
    color: #111 !important;
    background: #fff !important;
    box-shadow: none !important;
  }

  .preview-body pre,
  .preview-body blockquote,
  .preview-body table,
  .preview-body img,
  .preview-body svg {
    break-inside: avoid;
  }

  /* Print uses a light canvas regardless of the active app theme. Override
     both the fenced block and every syntax-highlighting span so dark-theme
     token colors cannot become unreadable in the PDF. */
  .preview-body pre {
    overflow: visible !important;
    white-space: pre-wrap !important;
    overflow-wrap: anywhere;
    color: #111827 !important;
    background: #f3f4f6 !important;
    border: 1px solid #d1d5db !important;
    box-shadow: none !important;
  }

  .preview-body pre code,
  .preview-body pre code * {
    color: #111827 !important;
    background: transparent !important;
    text-shadow: none !important;
  }

  .preview-body :not(pre) > code {
    color: #111827 !important;
    background: #f3f4f6 !important;
    border: 1px solid #e5e7eb;
    border-radius: 3px;
    padding: 0.08em 0.25em;
  }

  .preview-body a[href]::after {
    content: " (" attr(href) ")";
    font-size: 0.85em;
  }
}
